import base64
import pathlib
import subprocess
import zlib

PATCH_B64 = ""
SQL_B64 = ""
SCRIPT_PATH = pathlib.Path("scripts/apply_schedule_patch_20260702.py")
WORKFLOW_PATH = pathlib.Path(".github/workflows/apply-schedule-patch-20260702.yml")
PATCH_PATH = pathlib.Path("aff_schedule.patch")

PATCH_PATH.write_bytes(zlib.decompress(base64.b64decode(PATCH_B64)))
subprocess.run(["git", "apply", str(PATCH_PATH)], check=True)
PATCH_PATH.unlink(missing_ok=True)
pathlib.Path("supabase_product_schedules.sql").write_bytes(zlib.decompress(base64.b64decode(SQL_B64)))
SCRIPT_PATH.unlink(missing_ok=True)
WORKFLOW_PATH.unlink(missing_ok=True)

subprocess.run(["git", "config", "user.name", "github-actions[bot]"], check=True)
subprocess.run(["git", "config", "user.email", "41898282+github-actions[bot]@users.noreply.github.com"], check=True)
subprocess.run(["git", "add", "-A", "index.html", "supabase_product_schedules.sql", str(SCRIPT_PATH), str(WORKFLOW_PATH)], check=True)
if subprocess.run(["git", "diff", "--cached", "--quiet"]).returncode == 0:
    print("No changes to commit")
else:
    subprocess.run(["git", "commit", "-m", "Add multi-day product schedules"], check=True)
    subprocess.run(["git", "push"], check=True)
